rows = []

def positive(lang, label, text, reason, permitted=None, primitive=None):
    rows.append({'id': f'{lang}-P{sum(r["lang"] == lang and r["group"] == "positive" for r in rows)+1:02}', 'lang': lang, 'group': 'positive', 'subtype': 'single_shape_request', 'text': text, 'expected_label': label, 'permitted_labels': permitted or [label], 'primitive': primitive, 'reason': reason})

def hold(lang, subtype, text, reason):
    rows.append({'id': f'{lang}-H{sum(r["lang"] == lang and r["group"] == "hold" for r in rows)+1:02}', 'lang': lang, 'group': 'hold', 'subtype': subtype, 'text': text, 'expected_label': None, 'permitted_labels': [], 'primitive': None, 'reason': reason})

def ambiguous(lang, text, reason):
    rows.append({'id': f'{lang}-A{sum(r["lang"] == lang and r["group"] == "ambiguous" for r in rows)+1:02}', 'lang': lang, 'group': 'ambiguous', 'subtype': 'description_without_clear_request', 'text': text, 'expected_label': None, 'permitted_labels': [], 'primitive': None, 'reason': reason})

